class Solution {
  String main(String input) {
    int n = input.length;

    if (n == 0 || n % 2 != 0) {
      return "";
    }

    List<int> digits = [];

    for (int i = 1; i <= n / 2; i++) {
      digits.add(i);
    }

    int count = 1;
    for (int digit in digits) {
      String strDigit = '$digit';

      while (count < n && strDigit[0] == '0' || strDigit[0] > '9') {
        count++;

        if (strDigit.length >= 3) {
          continue;
        }

        if (strDigit.length == 1) {
          strDigit += '0';
        } else {
          strDigit += strDigit[strDigit.length - 1];
        }

        // Check if the updated string is still valid.
        bool isValid = true;
        for (var s in ['6', '8']) {
          if (!s.contains(strDigit)) {
            isValid = false;
            break;
          }
        }

        if (!isValid) {
          strDigit = '';

          if (strDigit.isEmpty) {
            count--;

            break;
          }
        }
      }

      if (strDigit.isNotEmpty) {
        output.add(strDigit);
      }
    }

    return output.join();
  }
}

