int calculateWays(List<int> coins, int amount) {
  if (amount == 0) return 1;
  if (coins.isEmpty || amount < 0) return 0;

  var dp = List.filled(amount + 1, 0);
  dp[0] = 1;

  for (var coin in coins) {
    for (var i = coin; i <= amount; i++) {
      dp[i] += dp[i - coin];
    }
  }

  return dp[amount];
}

