BigInt _modPow(BigInt base, BigInt exp, BigInt mod) {
  if (exp == BigInt.zero) return BigInt.one;

  BigInt halfPower = _modPow(base, exp.shiftRight(1), mod);
  BigInt squareHalfPower = halfPower * halfPower;

  if ((exp & BigInt.one) != BigInt.zero) {
    return (squareHalfPower * base) % mod;
  } else {
    return squareHalfPower % mod;
  }
}

