class BipartiteGraph {
  List<int> left; // Left part of the graph (0-indexed)
  List<List<int>> rightEdges; // Edges from left to right parts

  BipartiteGraph(int n, int m, List<int> edges) : 
        left = List.generate(n, (i) => i),
        rightEdges = List.filled(m, []) {
    for (int edge in edges) {
      if (edge >= n || edge < 0) throw ArgumentError("Invalid edge index");
      rightEdges[edge].add(edge);
    }
  }

  bool isBipartite() {
    final visited = List<bool>.filled(left.length + rightEdges.length, false);

    void dfs(int node, int color) {
      visited[node] = true;
      if (node < left.length) {
        for (int neighbor in rightEdges[node]) {
          if (!visited[neighbor]) {
            dfs(neighbor, -color);
          } else if (visited[neighbor] && (-1 * color) != visited[neighbor]) {
            return false; // Not bipartite
          }
        }
      } else {
        // Right nodes have no outgoing edges; just mark them as colored opposite.
        for (int i = 0; i < left.length; ++i) {
          if (!visited[i]) {
            return false; // Unvisited left node means not fully reachable or conflict
          }
        }
      }
      return true;
    }

    // Check all connected components: each should be properly colored.
    for (int i = 0; i < left.length; ++i) {
      if (!visited[i]) {
        if (!dfs(i, 1)) {
          return false;
        }
      }
    }
    return true;
  }
}

