      nodes[v].sib = nodes[u].sib;
      nodes[u].sib = 0;
      nodes[u].parent = v;
      nodes[v].child = u;
    } else {
      nodes[v].sib = nodes[t].child;
    }

    nodes[t].child = v;
    nodes[v].parent = t;
    t = v;
