class Graph {
  final List<List<Iterable>> adjacencyList = [];

  void addEdge(Edge e) {
    if(adjacencyList.isEmpty){
        adjacencyList.add([]);
    }

    if(e.startNode > adjacencyList.length - 1){
      while(e.startNode >= adjacencyList.length){
        adjacencyList.add([[]]);
      }
    }
    if(e.endNode > adjacencyList.length - 1){
      while(e.endNode >= adjacencyList.length){
        adjacencyList.add([[]]);
      }
    }
    adjacencyList[e.startNode].add(e.endNode);
    adjacencyList[e.endNode].add(e.startNode);
  }

  bool isCyclic() {
    var visitedNodes = [false] * adjacencyList.length;
    var recursionStack = [];
    for(var vertex in adjacencyList.keys.toList()) {
        if(!visitedNodes[vertex]){
            _checkForCycle(vertex, visitedNodes, recursionStack);
        }

    }

    return recursionStack.isNotEmpty;
  }

  bool _checkForCycle(int nodeIndex, List<bool> visitedNodes, List<int> recursionStack) {
      visitedNodes[nodeIndex] = true;
      recursionStack.add(nodeIndex);
      for(int neighbor in adjacencyList[nodeIndex]) {
        if(recursionStack.contains(neighbor)){
            return true;
        } else if(!visitedNodes[neighbor]) {
           bool cycleExists = _checkForCycle(neighbor, visitedNodes,recursionStack);
           if(cycleExists){
               return true;
           }
       }
   }

    recursionStack.removeLast();
    return false;
  }
}

