  static const List<int> _knownPrimes = [2, 3, 5, 7];

  /// Checks whether a given integer is prime.
  /// Returns true if the number is prime; otherwise returns false.
  bool isPrime(int n) {
    // Handle edge cases: numbers less than or equal to 1 are not prime.
    if (n <= 1) return false;

    // Numbers up to 8 can be directly checked against known primes.
    if (n < 9 && !_knownPrimes.contains(n)) return false;

