/*
This problem was asked by Microsoft.

Given a list of numbers, and a number K, return whether any two numbers from the list add up to K.
For example, given [10, 15, 3, 7] and K of 17, return true since 10 + 7 is 17.
*/


#include <vector>
using namespace std;



class Solution {
public:
    bool findTwoNumbersThatSum(vector<int>& nums, int sum) {
        vector<bool> seen(nums.size(), false);

        for (int i = 0; i < nums.size(); ++i) {
            if (!seen[i]) {
                int complement = sum - nums[i];

                // Check if complement exists in array
                for (int j = 0; j < nums.size(); ++j) {
                    if (nums[j] == complement && !seen[j]) {
                        return true;
                    }
                }

                // Mark current element as seen after checking all complements
                seen[i] = true;
            }
        }

        return false;
    }
};



void main() {
    vector<int> arr{10, 15, 3, 7};
    cout << "Should be True" << endl;
    Solution s;
    bool res = s.findTwoNumbersThatSum(arr, 17);
    cout << res << endl;
}

