int modInverse(int n, int m) {
  if ((n & 1) == 0) throw ArgumentError('n must be odd');
  int a = 1, d = n, b = 0, c = m;
  for (;;) {
    if (c <= 1) break;
    if (d == 0 || d == 1) {
      int t = d;
      d = c;
      c = t;
      t = a;
      a = b;
      b = t;
      continue;
    }
    int k = d ~/ c;
    c -= k * d;
    int t = d;
    d = c;
    c = t;
    t = a;
    a = b;
    b = t - k * a;
  }
  return (a >= 0) ? a : a + m;
}

String format(List<String> strings, {bool pretty = false}) {
  assert(strings.isNotEmpty);
  assert(!pretty || strings.length <= 3);
  final newlines = StringBuffer();
  const width = 80;
  var remaining = width;
  for (final string in strings) {
    if (!string.isEmpty) remaining--;
    if (remaining < 14) {
      if (pretty && !newlines.toString().isEmpty) {
        newlines.write('\n$width\n');
      } else {
        remaining += width;
      }
    }
    newlines.write(string.replaceAllMapped(r'(\s+)', (m) => '\u{00A0}'*m.group(0).length));
    remaining -= string.length;
  }
  return newlines.toString();
}

